int bnep_add_connection(struct bnep_connadd_req *req, struct socket *sock) {
    struct net_device *dev;
    struct bnep_session *session;
    int ret = -EINVAL;

    if (!sock) {
        return -EINVAL;
    }

    dev = alloc_netdev(sizeof(struct bnep_session), "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev) {
        return -ENOMEM;
    }

    session = netdev_priv(dev);
    session->sock = sock;
    session->role = req->role;

    memcpy(session->src_addr, req->src, BNEP_ADDR_LEN);
    memcpy(session->dst_addr, req->dst, BNEP_ADDR_LEN);

    if (bnep_session_exists(session->dst_addr)) {
        if (bnep_session_is_connected(session->dst_addr)) {
            free_netdev(dev);
            return -EEXIST;
        }
    }

    if (req->flags & BNEP_CONNADD_FLAG_MULTICAST) {
        session->multicast = true;
        session->proto_filters = req->proto_filters;
    }

    if (register_netdev(dev) < 0) {
        free_netdev(dev);
        return -EIO;
    }

    session->thread = kthread_run(bnep_session_handler, session, "bnep_thread");
    if (IS_ERR(session->thread)) {
        unregister_netdev(dev);
        free_netdev(dev);
        return PTR_ERR(session->thread);
    }

    memcpy(req->dev_name, dev->name, IFNAMSIZ);

    ret = 0;
    return ret;
}

int bnep_add_connection(struct bnep_connadd_req *req, struct socket *sock) {
    struct net_device *dev;
    int err = -EINVAL;

    if (!sock)
        return err;

    dev = alloc_netdev(0, "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    memcpy(dev->dev_addr, req->src, BNEP_ADDR_LEN);
    memcpy(dev->broadcast, req->dst, BNEP_ADDR_LEN);

    if (is_connected_session(dev->broadcast)) {
        free_netdev(dev);
        return -EEXIST;
    }

    setup_session(dev, req->role);
    if (req->multicast)
        enable_multicast_filters(dev);

    if (req->proto_filters)
        setup_protocol_filters(dev, req->proto_filters);

    register_netdev(dev);

    err = create_kernel_thread(handle_session, dev);
    if (err < 0) {
        unregister_netdev(dev);
        free_netdev(dev);
        return err;
    }

    strncpy(req->dev_name, dev->name, IFNAMSIZ);
    return 0;
}

int bnep_connadd(struct bnep_connadd_req *req, struct socket *sock)
{
    struct net_device *dev;
    int err;

    if (!sock) {
        return -EINVAL;
    }

    dev = alloc_netdev(sizeof(struct bnep_session), "bnep%d",
                       NET_NAME_UNKNOWN, bnep_setup);
    if (!dev) {
        return -ENOMEM;
    }

    /* Retrieve source and destination addresses from the request */
    memcpy(dev->dev_addr, req->src, BNEP_ADDR_LEN);
    memcpy(dev->broadcast, req->dst, BNEP_ADDR_LEN);

    /* Check for existing session */
    if (bnep_session_exists(dev->broadcast)) {
        free_netdev(dev);
        return -EEXIST;
    }

    /* Initialize session structure */
    netdev_priv(dev) = kzalloc(sizeof(struct bnep_session), GFP_KERNEL);
    if (!netdev_priv(dev)) {
        free_netdev(dev);
        return -ENOMEM;
    }

    /* Setup multicast and protocol filters */
    if (req->flags & BNEP_CONNADD_FLAG_MULTICAST) {
        bnep_setup_multicast(dev);
    }

    if (req->flags & BNEP_CONNADD_FLAG_PROTO_FILTER) {
        bnep_setup_proto_filter(dev, req->proto_filters);
    }

    /* Register the network device */
    err = register_netdev(dev);
    if (err < 0) {
        kfree(netdev_priv(dev));
        free_netdev(dev);
        return err;
    }

    /* Create kernel thread to handle the session */
    err = bnep_session_thread_start(dev, sock);
    if (err < 0) {
        unregister_netdev(dev);
        kfree(netdev_priv(dev));
        free_netdev(dev);
        return err;
    }

    /* Update the request structure with device name */
    snprintf(req->dev_name, IFNAMSIZ, "%s", dev->name);

    return 0;
}

int bnep_connadd(struct bnep_connadd_req *req, struct socket *sock) {
    struct net_device *dev;
    int err = -EINVAL;

    if (!sock)
        return err;

    dev = alloc_netdev(0, "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    memcpy(dev->dev_addr, req->src, BNEP_ADDR_LEN);
    memcpy(dev->broadcast, req->dst, BNEP_ADDR_LEN);

    if (bnep_session_exists(dev->broadcast)) {
        if (bnep_session_connected(dev->broadcast)) {
            free_netdev(dev);
            return -EEXIST;
        }
    }

    struct bnep_session *session = kzalloc(sizeof(*session), GFP_KERNEL);
    if (!session) {
        free_netdev(dev);
        return -ENOMEM;
    }

    session->dev = dev;
    memcpy(session->src, req->src, BNEP_ADDR_LEN);
    memcpy(session->dst, req->dst, BNEP_ADDR_LEN);
    session->role = req->role;

    if (req->flags & BNEP_CONN_FLAGS_MULTICAST) {
        dev->flags |= IFF_MULTICAST;
    }

    if (req->flags & BNEP_CONN_FLAGS_PROTO_FILTER) {
        bnep_proto_set_filter(dev, req->filter);
    }

    if (register_netdev(dev) < 0) {
        kfree(session);
        free_netdev(dev);
        return -EIO;
    }

    if (kthread_run(bnep_session_thread, session, "bnepd") == NULL) {
        unregister_netdev(dev);
        kfree(session);
        free_netdev(dev);
        return -EAGAIN;
    }

    memcpy(req->dev_name, dev->name, IFNAMSIZ);

    return 0;
}

